import React from 'react';
import { Link } from 'react-router-dom';

const sidebarStyle = {
    width: '200px',
    minHeight: '100vh',
    background: '#f8f9fa',
    borderRight: '1px solid #dee2e6',
    padding: '20px 0',
};

const brandStyle = {
    fontSize: '20px',
    fontWeight: '700',
    color: '#343a40',
    padding: '0 20px 20px',
    borderBottom: '1px solid #dee2e6',
    marginBottom: '10px',
};

const linkStyle = {
    display: 'block',
    padding: '10px 20px',
    color: '#495057',
    textDecoration: 'none',
    fontSize: '14px',
};

const Sidebar = ({ role }) => {
    return (
        <div style={sidebarStyle}>
            <div style={brandStyle}>EMS</div>
            <nav>
                {role === 'ADMIN' && (
                    <>
                        <Link to="/" style={linkStyle}>Dashboard</Link>
                        <Link to="/add-employee/_add" style={linkStyle}>Add Employee</Link>
                    </>
                )}
                {role === 'EMPLOYEE' && (
                    <Link to="/dashboard" style={linkStyle}>My Profile</Link>
                )}
            </nav>
        </div>
    );
};

export default Sidebar;
